function buildTemplate(item) {
  const base = BASE_TEMPLATES.find(template => template.id === item.baseId);
  return {
    ...(base || {}),
    id: item.id,
    group: item.group,
    category: base?.category || item.group,
    label: item.label,
    desc: base?.desc ? `?? ${base.desc}` : `${item.label} JSP ??`,
    sourceFile: `src/common/chungnam/pub/${item.file}`,
    previewStyle: `${CHUNGNAM_PREVIEW_STYLE}
${base?.previewStyle || ''}`,
    previewHeight: base?.previewHeight,
    code: item.code,
    applyMapping: base?.applyMapping,
  };
}

export default TEMPLATE_DATA.map(buildTemplate);
